contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function driving the contract
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // Record c's balance before any action
        uint beforeC = address(c).balance;

        // Make a deposit on behalf of this test contract to set credit[msg.sender]
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // After deposit, c's balance must have increased by depositAmount
        uint afterDepositC = address(c).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe c's balance after the withdraw attempt
        uint afterWithdrawC = address(c).balance;

        // If withdraw reverted, c's balance must be unchanged from afterDepositC.
        // If withdraw succeeded, c's balance must have decreased by exactly depositAmount.
        // Also, on success the contract should no longer be able to withdraw that credit again:
        // calling withdrawAll a second time must revert or not change c's balance further.
        bool secondReverted;
        uint midBalance = afterWithdrawC;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        uint finalBalance = address(c).balance;

        assert(
            // after making the deposit, the contract's balance increased by depositAmount
            afterDepositC == beforeC + depositAmount
            && (
                // Case: first withdraw reverted -> no change in c's balance and second withdraw also makes no further decrease
                (reverted && afterWithdrawC == afterDepositC && finalBalance == afterDepositC)
                ||
                // Case: first withdraw succeeded -> c lost exactly depositAmount and subsequent withdraw cannot decrease it further
                (!reverted && afterWithdrawC + depositAmount == afterDepositC && finalBalance == afterWithdrawC)
            )
        );
    }

    receive() external payable { }
}

