pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeC = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterWithdrawC = address(c).balance;
        bool secondReverted;
        uint midBalance = afterWithdrawC;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint finalBalance = address(c).balance;
        assertTrue(afterDepositC == beforeC + depositAmount
            && (
                // Case: first withdraw reverted -> no change in c's balance and second withdraw also makes no further decrease
                (reverted && afterWithdrawC == afterDepositC && finalBalance == afterDepositC)
                ||
                // Case: first withdraw succeeded -> c lost exactly depositAmount and subsequent withdraw cannot decrease it further
                (!reverted && afterWithdrawC + depositAmount == afterDepositC && finalBalance == afterWithdrawC)
            ));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
